        function cancelVideoSoundFade() {
            if (videoSoundFadeFrame) cancelAnimationFrame(videoSoundFadeFrame);
            videoSoundFadeFrame = null;
        }

        function fadeVideoVolume(videoElement, target, duration, onComplete, easing = 'out') {
            cancelVideoSoundFade();
            const clampVolume = (value) => Math.max(0, Math.min(1, Number(value) || 0));
            const from = clampVolume(videoElement.volume);
            const safeTarget = clampVolume(target);
            const started = performance.now();
            const ease = (progress) => {
                if (easing === 'inOut') {
                    return progress < 0.5
                        ? 4 * progress * progress * progress
                        : 1 - Math.pow(-2 * progress + 2, 3) / 2;
                }
                return 1 - Math.pow(1 - progress, 3);
            };
            const step = (now) => {
                // Some mobile browsers can deliver the first animation-frame
                // timestamp just before the performance.now() sample above,
                // especially while their address bar changes the visual
                // viewport. Clamp both ends so the interpolation can never
                // assign an invalid media volume and interrupt the homepage.
                const progress = Math.max(0, Math.min(1, (now - started) / duration));
                const eased = ease(progress);
                videoElement.volume = clampVolume(from + ((safeTarget - from) * eased));
                if (progress < 1) {
                    videoSoundFadeFrame = requestAnimationFrame(step);
                    return;
                }
                videoSoundFadeFrame = null;
                if (onComplete) onComplete();
            };
            videoSoundFadeFrame = requestAnimationFrame(step);
        }

